async (page) => {
  const found = await page.evaluate(async () => {
    const list = document.querySelector('[aria-label="Inventory"]');
    let el = list; 
    while (el && el.scrollHeight <= el.clientHeight) el = el.parentElement;
    el = el || document.scrollingElement;
    el.scrollTop = 0;
    for (let i = 0; i < 2000; i++) {
      await new Promise(r => setTimeout(r, 30));
      const hit = [...document.querySelectorAll('code')].find(c => c.textContent.trim() === 'HAK-5638');
      if (hit) { hit.scrollIntoView({block:'center'}); return true; }
      const prev = el.scrollTop;
      el.scrollTop += el.clientHeight * 0.8;
      if (el.scrollTop === prev) return false;
    }
    return false;
  });
  if (!found) return 'not found';
  const item = page.locator('[role=listitem], li').filter({has: page.locator('code', {hasText: 'HAK-5638'})});
  await item.getByRole('button', {name: 'Select'}).click();
  return await item.innerText();
}

